def save(name,body,desktop=False):
 (D/f'after-{name}.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+name+' — proposed UI</title><link rel="stylesheet" href="design.css"><body>'+body+'<script>if(new URLSearchParams(location.search).get("theme")==="dark")document.body.classList.add("dark")</script></body></html>')
